/** @param {string} structureId @param {number} rank */
export function lookupTransferRule(structureId, rank) {
  const structure = transferRules.structures.find(item => item.id === structureId);
  const row = structure?.ranks.find(item => item.rank === rank);
  return structure && row ? { ...row, structureId: structure.id, structure: structure.label, version: transferRules.version } : null;
}
